<?php

declare(strict_types=1);

// The calls of host protocol 1. Generated by php artisan journal:host-protocol from protocol/host.json; do not edit.

use App\Hosts\Protocol\Http\AnswerOrderController;
use App\Hosts\Protocol\Http\ClaimOrdersController;
use App\Hosts\Protocol\Http\NotifyHeartbeatController;
use App\Hosts\Protocol\Http\NotifyInventoryController;
use App\Hosts\Protocol\Http\NotifyProcessOutputController;
use App\Hosts\Protocol\Http\NotifyProcessReportController;
use App\Hosts\Protocol\Http\NotifyProjectReadController;
use App\Hosts\Protocol\Http\PullPrivateValueController;
use App\Projects\Enums\HostRouteRole;
use Illuminate\Support\Facades\Route;

Route::prefix('host')
    ->middleware('journal.host:'.HostRouteRole::Shared->value)
    ->name('agents.host.')
    ->group(function (): void {
        Route::post('/orders/claim', ClaimOrdersController::class)->name('orders.claim');
        Route::post('/orders/{order}', AnswerOrderController::class)->name('orders.answer');
        Route::post('/private-values/{submission}', PullPrivateValueController::class)->name('private-values.pull');
        Route::post('/processes/{process}/output', NotifyProcessOutputController::class)->name('processes.output');
        Route::post('/processes/{process}', NotifyProcessReportController::class)->name('processes.report');
        Route::post('/inventory', NotifyInventoryController::class)->name('inventory');
        Route::post('/heartbeat', NotifyHeartbeatController::class)->name('heartbeat');
        Route::post('/reports/project-reads/{read}', NotifyProjectReadController::class)->name('reports.project-reads');
    });
